import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Cart Rule Coupons","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/cart-rule-coupons/index.md","filePath":"api/rest-api/admin/marketing/promotions/cart-rule-coupons/index.md"}'),n={name:"api/rest-api/admin/marketing/promotions/cart-rule-coupons/index.md"};function s(i,e,c,d,p,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="cart-rule-coupons" tabindex="-1">Cart Rule Coupons <a class="header-anchor" href="#cart-rule-coupons" aria-label="Permalink to &quot;Cart Rule Coupons&quot;">​</a></h1><p>A <strong>cart rule coupon</strong> is a code a shopper enters at checkout to activate a coupon-gated cart rule. These coupons belong to a single cart rule and are managed from the <strong>Coupons</strong> tab of the admin <strong>Marketing → Promotions → Cart Rules</strong> screen.</p><h2 id="how-cart-rule-coupons-work" tabindex="-1">How cart rule coupons work <a class="header-anchor" href="#how-cart-rule-coupons-work" aria-label="Permalink to &quot;How cart rule coupons work&quot;">​</a></h2><p>A cart rule can be set to apply automatically when its conditions match, or to require a specific code — that&#39;s the <code>couponType</code> field on the rule. When the rule is coupon-gated (<code>couponType</code> <code>1</code>), its discount only kicks in once the shopper enters a matching code at the cart.</p><p>Each rule has exactly one <strong>primary</strong> code (the rule&#39;s own code, <code>isPrimary</code><code>true</code>), which is set on the cart rule itself. Everything managed here are the rule&#39;s <strong>secondary</strong> codes (<code>isPrimary</code> <code>false</code>) — extra codes that activate the same discount. There are two ways to add them:</p><ul><li><strong>Create one</strong> — add a single code with <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.html">Create</a>.</li><li><strong>Generate many</strong> — <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-generate.html">Generate</a> makes a batch of random codes from a chosen length, character format, and optional prefix/suffix — useful for unique single-use codes in a campaign.</li></ul><p><strong>Usage limits.</strong> <code>usageLimit</code> caps total redemptions across all customers and <code>usagePerCustomer</code> caps redemptions per shopper (<code>0</code> means unlimited for either). When omitted on create or generate, both inherit the parent rule&#39;s settings. <code>timesUsed</code> records how often a code has been redeemed and is read-only.</p><p><strong>Scoping.</strong> Coupons always belong to one cart rule. Every endpoint is nested under that rule&#39;s id, and a coupon from another rule is never returned or deleted across rules.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-list.html">List</a></td><td><code>GET /api/admin/marketing/cart-rules/{cartRuleId}/coupons</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.html">Create</a></td><td><code>POST /api/admin/marketing/cart-rules/{cartRuleId}/coupons</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-generate.html">Generate</a></td><td><code>POST /api/admin/marketing/cart-rules/{cartRuleId}/coupons/generate</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/cart-rules/{cartRuleId}/coupons/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/cart-rules/{cartRuleId}/coupons/mass-delete</code></td></tr></tbody></table><p>These coupons belong to <a href="/api/rest-api/admin/marketing/promotions/cart-rules/">Cart Rules</a> — the parent rule decides whether a code is required and what discount it applies.</p><p>All Cart Rule Coupons endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',12)]))}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
